package jp.tapmarker;
import java.util.*;

public class RecordedAutomatonRepairTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static RecordedAutomatonGenerator.Model recording(int... sequence){return RecordedAutomatonGeneratorTest.model(sequence);}
 static PhaseEngine baseline(){RecordedAutomatonGenerator.Model m=recording(0,1,0);m.annotate(0,PhaseEngine.CENTER,new float[]{.31f,.72f},60,1);m.annotate(1,PhaseEngine.CENTER,new float[]{.7f,.76f},60,0);return RecordedAutomatonGenerator.compile(m).engine;}
 static void addReviewed(RecordedAutomatonGenerator.Model m){for(RecordedAutomatonGenerator.State state:m.states)if(m.destinations(state.index).length>0&&state.action==RecordedAutomatonGenerator.UNREVIEWED)m.annotate(state.index,PhaseEngine.CENTER,new float[]{.7f,.76f},60,m.destinations(state.index)[0]);}
 static PhaseEngine.Watch observe(PhaseEngine e,ObservationLearner.Frame frame,long at){Map<String,float[]> samples=ObservationLearnerTest.samples(e,frame);e.observe(samples,at);check(e.poll()==null,"first frame does not enter repaired branch");e.observe(samples,at+300);return e.poll();}
 static void iterative(){
  PhaseEngine before=baseline();String identity=BancGraphIdentity.of("game",before);RecordedAutomatonGenerator.Model model=recording(0,1,0,2,0,2);
  RecordedAutomatonRepair.Audit audit=RecordedAutomatonRepair.analyze(before,model);check(audit.recognized==2&&audit.unknown==1,"new recording identifies exact unregistered appearance");check(audit.issues.stream().anyMatch(i->i.state==2&&i.at>=0),"repair issues retain recording state and time");
  check(RecordedAutomatonRepair.inheritReviewed(before,model)==2,"previous reviewed tap positions reused for matched source/destination states");check(model.states.get(0).path[0]==.31f,"inheritance keeps already registered point, without inventing another");
  RecordedAutomatonRepair.Result draft=RecordedAutomatonRepair.compile(before,model,false);check(draft.pending==1&&draft.engine.recordingReviewRequired,"unknown operation remains blocked even with repair candidates");check(before.phases.size()==4&&BancGraphIdentity.of("game",before).equals(identity),"candidate generation does not mutate active graph");
  addReviewed(model);RecordedAutomatonRepair.Result repaired=RecordedAutomatonRepair.compile(before,model,true);check(repaired.pending==0&&repaired.engine.validateStart().isEmpty(),"reviewed candidate validates before application");check(repaired.after.unknown==0&&repaired.after.ambiguous==0,"same recording is reclassified after repair");check(repaired.engine.phases.keySet().containsAll(before.phases.keySet()),"pre-existing states survive incremental repair");check(repaired.engine.rule("record:input:0")!=null&&repaired.engine.rule("record:input:1")!=null,"existing operation IDs retained for action history");
  PhaseEngine e=repaired.engine;e.enter(repaired.recordingStart,0);PhaseEngine.Watch input=observe(e,model.states.get(0).frame,1000);check(input!=null&&input.action==PhaseEngine.CENTER&&input.touchPoint[0]==.31f,"repaired input uses prior reviewed operation");e.finish(input,1400);check(e.current.contains("verify"),"repair still waits for actual input result");PhaseEngine.Watch result=observe(e,model.states.get(2).frame,1600);check(result!=null&&result.action==PhaseEngine.WAIT,"new recorded alternate result works from verification phase");e.finish(result,2000);check(e.current.equals(repaired.after.mapped.get(2)),"alternate result enters its own repaired action state");
  RecordedAutomatonRepair.Result again=RecordedAutomatonRepair.compile(repaired.engine,model,true);check(again.addedStates==0&&again.changedRules==0,"same recording can be repeated without duplicate graph growth");
  RecordedAutomatonGenerator.Model latest=recording(0,1,0,2,0,2);check(RecordedAutomatonRepair.inheritReviewed(repaired.engine,latest)==2,"next iteration reuses clear reviewed operations; multi-outcome action stays for review");addReviewed(latest);RecordedAutomatonRepair.Result subsequent=RecordedAutomatonRepair.compile(repaired.engine,latest,true);check(subsequent.after.unknown==0,"next recording is checked against current improved graph");
 }
 static void boundaries(){
  RecordedAutomatonGenerator stalled=new RecordedAutomatonGenerator();for(int i=0;i<18;i++)stalled.add(i*500,ObservationLearnerTest.frame(2));RecordedAutomatonGenerator.Model stopped=stalled.finishForRepair();check(stopped.states.size()==1&&stopped.edges.isEmpty(),"single frozen screen can still be diagnosed in repair mode");RecordedAutomatonRepair.Result unchanged=RecordedAutomatonRepair.compile(baseline(),stopped,true);check(unchanged.before.unknown==1&&unchanged.before.issues.stream().anyMatch(i->i.kind.contains("長時間")),"frozen recording identifies missing appearance and long unchanged display");check(unchanged.changedRules==0&&unchanged.addedStates==0&&AutomatonGraph.sameConfiguration(unchanged.engine,baseline()),"no recorded result means no invented input or graph replacement");
  PhaseEngine base=baseline();RecordedAutomatonGenerator.Model end=recording(0,2);end.annotate(0,PhaseEngine.CENTER,new float[]{.31f,.72f},60,1);RecordedAutomatonRepair.Result result=RecordedAutomatonRepair.compile(base,end,true);String finalPhase=result.after.mapped.get(1);check(finalPhase!=null&&!result.engine.phases.get(finalPhase).terminal,"video end does not become a terminal or daily completion");check(result.engine.phases.get(finalPhase).watches.stream().allMatch(w->w.action==PhaseEngine.WAIT),"recording end only observes current appearance");
  base.recordingReviewRequired=true;RecordedAutomatonGenerator.Model m=recording(0,1,0);check(RecordedAutomatonRepair.inheritReviewed(base,m)==0,"unreviewed baseline cannot provide executable inherited actions");addReviewed(m);result=RecordedAutomatonRepair.compile(base,m,false);check(result.engine.recordingReviewRequired,"existing recording review gate cannot be bypassed by repair");
  base=baseline();PhaseEngine.Phase conflicting=new PhaseEngine.Phase();conflicting.id="different";conflicting.name="different";conflicting.watches.add(PhaseEngine.copyWatch(base.rule("record:input:0")));conflicting.watches.get(0).id="different-input";base.phases.put(conflicting.id,conflicting);m=recording(0,1,0);check(RecordedAutomatonRepair.analyze(base,m).ambiguous>0,"same appearance with conflicting state mapping is identified");check(RecordedAutomatonRepair.inheritReviewed(base,m)==0,"ambiguous source or destination does not inherit a guessed tap");
  try{RecordedAutomatonRepair.compile(new PhaseEngine(),recording(0,1),false);throw new AssertionError();}catch(IllegalArgumentException expected){checks++;}
 }
 static void mixedCoordinates(){
  PhaseEngine base=baseline();base.windowRelative=false;RecordedAutomatonGenerator.Model m=recording(0,2,0);addReviewed(m);RecordedAutomatonRepair.Result result=RecordedAutomatonRepair.compile(base,m,true);
  check(!result.engine.windowRelative&&result.engine.regions.values().stream().anyMatch(r->r.windowLocal),"new portable repair regions coexist with existing screen-coordinate graph");for(PhaseEngine.Region r:base.regions.values())check(!result.engine.regions.get(r.id).windowLocal&&Arrays.equals(r.bounds,result.engine.regions.get(r.id).bounds),"existing region coordinate contract retained");
  PhaseEngine e=result.engine;PhaseEngine.Watch input=e.phases.get(e.initial).watches.get(0);Map<String,float[]> samples=new HashMap<>();samples.put("old-anchor",new float[]{.4f});ObservationLearner.Frame f=m.states.get(0).frame;RegionSampler.Pixels pixels=(x,y)->{if(x<100||x>=500||y<100||y>=700)return 0xff010101;int px=Math.min(f.width-1,(x-100)*f.width/400),py=Math.min(f.height-1,(y-100)*f.height/600);return f.pixels[py*f.width+px];};
  RecordedRepairSampling.sample(e,samples,e.activeRegions(),800,800,pixels,new int[]{100,100,500,700});check(samples.get("old-anchor")[0]==.4f,"repair sampling does not replace unrelated anchors");check(samples.containsKey(input.regionId)&&samples.get(RecordedRepairSampling.WINDOW)[2]==400,"repair anchors sampled inside actual target window");float[] point=RecordedRepairSampling.point(e,input,samples,800,800);check(point!=null&&Math.abs(point[0]-380)<.01f&&Math.abs(point[1]-556)<.01f,"reviewed .7/.76 coordinates mapped to current window, not other app");
  input.action=PhaseEngine.CURVE;input.relativeCurve=true;input.curve=new float[]{.1f,.2f,.8f,.9f};float[] path=RecordedRepairSampling.path(e,input,samples,800,800);check(path!=null&&path[0]==140&&path[1]==220&&path[2]==420&&path[3]==640,"reviewed curve shares current window coordinate contract");check(RecordedRepairSampling.point(e,input,new HashMap<>(),800,800)==null,"missing current window prevents input");
  check(e.runtimeCopy().regions.get(input.regionId).windowLocal,"repair coordinate metadata survives runtime copy");
  samples.put(RecordedRepairSampling.ADAPTIVE,new float[]{0});check(RecordedRepairSampling.point(e,input,samples,800,800)==null,"unconfirmed recording alignment cannot provide an input point");
 }
 static void recordedAlignment()throws Exception{
  Video6687ReplayTest.load();RecordedAutomatonGenerator generator=new RecordedAutomatonGenerator();long at=0;
  for(String id:new String[]{"30-native","111.8-native","30-native"}){VirtualPresetProfileTest.Image im=Video6687ReplayTest.images.get(id);ObservationLearner.Frame frame=ObservationLearner.Frame.capture(im.width,im.height,im);frame.excluded=new float[]{.32f,.37f,1,.61f};for(int i=0;i<4;i++){generator.add(at,frame);at+=500;}}
  RecordedAutomatonGenerator.Model model=generator.finish();for(RecordedAutomatonGenerator.State state:model.states)model.annotate(state.index,PhaseEngine.CENTER,new float[]{.5f,.75f},60,model.destinations(state.index)[0]);
  PhaseEngine base=baseline();base.windowRelative=false;RecordedAutomatonRepair.Result repair=RecordedAutomatonRepair.compile(base,model,true);PhaseEngine e=repair.engine;VirtualPresetProfileTest.Image source=Video6687ReplayTest.images.get("30-native");Map<String,float[]> samples=new HashMap<>();
  RegionSampler.Pixels pixels=(x,y)->{float nx=(x-80)/640f,ny=((y-40)/1440f-.05f)/.9f;if(nx<0||nx>=1||ny<0||ny>=1)return 0xff18202f;return source.get(Math.min(source.width-1,(int)(nx*source.width)),Math.min(source.height-1,(int)(ny*source.height)));};
  RecordedRepairSampling.sample(e,samples,e.activeRegions(),800,1520,pixels,new int[]{80,40,720,1480});LearnedLayout layout=new LearnedLayout();RecordedRepairSampling.adapt(e,samples,800,1520,pixels,layout,1000);PhaseEngine.Watch input=e.phases.get(e.current).watches.get(0);float[] point=RecordedRepairSampling.point(e,input,samples,800,1520);
  check(point==null&&!layout.confirmed||point!=null&&layout.confirmed&&Math.abs(point[1]-(40+(.05f+.75f*.9f)*1440))<26,"recorded crop differences either locate the real reviewed point or hold ambiguous input / "+layout.status);
  Map<String,float[]> exact=new HashMap<>();RegionSampler.Pixels nativePixels=(x,y)->source.get(Math.min(source.width-1,Math.max(0,(x-80)*source.width/640)),Math.min(source.height-1,Math.max(0,(y-40)*source.height/1440)));RecordedRepairSampling.sample(e,exact,e.activeRegions(),800,1520,nativePixels,new int[]{80,40,720,1480});LearnedLayout nativeLayout=new LearnedLayout();RecordedRepairSampling.adapt(e,exact,800,1520,nativePixels,nativeLayout,2000);float[] nativePoint=RecordedRepairSampling.point(e,input,exact,800,1520);check(nativePoint!=null&&Math.abs(nativePoint[1]-1120)<20,"actual recorded glyphs provide the reviewed target at their native crop / "+nativeLayout.status);check(repair.after.unknown==0&&repair.after.ambiguous==0,"real recorded appearances are revalidated against improved graph");
 }
 public static void main(String[] args)throws Exception{iterative();boundaries();mixedCoordinates();recordedAlignment();System.out.println("RecordedAutomatonRepairTest: "+checks+" checks passed; iterative recording audits, incremental repair, preserved history, revalidation, mixed coordinates and recorded alignment; device decoder/input untested");}
}
